def _opencode_stable_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function value(object, keys) {{
  if (!object || typeof object !== "object") return undefined
  for (const key of keys) if (object[key] !== undefined && object[key] !== null) return object[key]
  for (const child of Object.values(object)) {{
    const found = value(child, keys)
    if (found !== undefined) return found
  }}
}}

function text(object) {{
  if (typeof object === "string") return object
  if (Array.isArray(object)) return object.map(text).filter(Boolean).join("\\n")
  if (!object || typeof object !== "object") return ""
  if (typeof object.text === "string") return object.text
  for (const key of ["content", "parts", "message", "delta"]) {{
    const found = text(object[key])
    if (found) return found
  }}
  return ""
}}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

export const CodeKnowledgeBuilderSync = async ({{ directory, worktree }}) => {{
  const cwd = worktree || directory || process.cwd()
  const assistants = new Map()
  return {{
    event: async ({{ event }}) => {{
      const data = event?.properties ?? event?.data ?? event ?? {{}}
      const info = data?.info ?? data
      const sessionID = String(value(info, ["sessionID", "sessionId", "session_id", "id"]) ?? "session-unknown")
      const base = {{ session_id: sessionID, cwd }}
      if (event?.type === "session.created") emit({{ ...base, hook_event_name: "SessionStart", source: "startup", event_id: `session-created:${{sessionID}}` }})
      if (event?.type === "message.updated") {{
        const role = String(value(info, ["role"]) ?? "").toLowerCase()
        const body = text(info)
        const messageID = String(value(info, ["messageID", "messageId", "id"]) ?? "")
        if (role === "user") emit({{ ...base, hook_event_name: "UserPromptSubmit", prompt: body, event_id: `message:${{messageID}}` }})
        if (role === "assistant") {{
          assistants.set(sessionID, body)
          emit({{ ...base, hook_event_name: "AssistantMessage", assistant_message: body, event_id: `message:${{messageID}}` }})
        }}
      }}
      if (event?.type === "command.executed") {{
        const commandName = String(value(data, ["command", "commandName", "name"]) ?? "")
        if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ ...base, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
      }}
      if (event?.type === "file.edited") emit({{ ...base, hook_event_name: "FileChanged", file_path: value(data, ["file", "filePath", "path"]), event: "change" }})
      if (event?.type === "session.compacted") emit({{ ...base, hook_event_name: "PostCompact", trigger: "auto" }})
      if (event?.type === "session.idle") emit({{ ...base, hook_event_name: "Stop", last_assistant_message: assistants.get(sessionID) ?? "", stop_hook_active: false }})
      if (event?.type === "session.deleted") emit({{ ...base, hook_event_name: "SessionEnd", reason: "other" }})
    }},
    "tool.execute.after": async (input, output) => {{
      emit({{
        session_id: String(input?.sessionID ?? input?.sessionId ?? "session-unknown"),
        cwd,
        hook_event_name: "PostToolUse",
        tool_name: String(input?.tool ?? "unknown"),
        tool_use_id: String(input?.callID ?? input?.toolCallID ?? input?.id ?? ""),
        tool_input: input?.args ?? input?.input ?? input,
        tool_response: output,
        status: "completed",
      }})
    }},
  }}
}}
'''

def _opencode_v2_plugin(python: Path, ckb: Path, registry: Path) -> str:
    command_args = ["-X", "utf8", str(ckb), "automation", "hook", "--harness", "opencode-v2", "--registry", str(registry)]
    return f'''import {{ spawnSync }} from "node:child_process"
import {{ Plugin }} from "@opencode-ai/plugin"

const PYTHON = {json.dumps(str(python))}
const ARGS = {json.dumps(command_args)}

function emit(payload) {{
  try {{
    const event = {{ ...payload, harness_pid: process.pid }}
    spawnSync(PYTHON, ARGS, {{ input: JSON.stringify(event), encoding: "utf8", timeout: payload?.ckb_skill_applied ? 20000 : 8000, windowsHide: true }})
  }} catch {{}}
}}

function messageText(message) {{
  const parts = message?.parts ?? message?.content ?? []
  if (typeof parts === "string") return parts
  return Array.isArray(parts) ? parts.map((part) => typeof part === "string" ? part : part?.text ?? "").filter(Boolean).join("\\n") : ""
}}

function unwrapMessages(value) {{
  if (Array.isArray(value)) return value
  if (Array.isArray(value?.data)) return value.data
  if (Array.isArray(value?.messages)) return value.messages
  return []
}}

function eventSessionID(event) {{
  return String(event?.sessionID ?? event?.properties?.sessionID ?? event?.data?.sessionID ?? "session-unknown")
}}

function eventCwd(event) {{
  return String(event?.cwd ?? event?.location?.directory ?? event?.properties?.cwd ?? event?.data?.cwd ?? process.cwd())
}}

export default Plugin.define({{
  id: "code-knowledge-builder.sync",
  setup: async (ctx) => {{
    const seenSessions = new Set()
    const sessionCwds = new Map()
    await ctx.session.hook("context", (event) => {{
      const sessionID = String(event.sessionID ?? "session-unknown")
      const cwd = eventCwd(event)
      sessionCwds.set(sessionID, cwd)
      if (!seenSessions.has(sessionID)) {{
        seenSessions.add(sessionID)
        emit({{ session_id: sessionID, cwd, hook_event_name: "SessionStart", source: "startup", event_id: `session:${{sessionID}}` }})
      }}
      const messages = Array.isArray(event.messages) ? event.messages : []
      const latest = [...messages].reverse().find((item) => item?.role === "user")
      if (latest) emit({{ session_id: sessionID, cwd, hook_event_name: "UserPromptSubmit", prompt: messageText(latest), event_id: `message:${{latest.id ?? latest.messageID ?? "latest"}}` }})
    }})
    await ctx.tool.hook("execute.after", (event) => {{
      emit({{
        session_id: String(event.sessionID ?? "session-unknown"),
        cwd: String(event.cwd ?? process.cwd()),
        hook_event_name: "PostToolUse",
        tool_name: String(event.tool ?? "unknown"),
        tool_use_id: String(event.toolCallID ?? event.callID ?? ""),
        tool_input: event.input,
        tool_response: event.status === "error" ? event.error : event.result,
        output_paths: event.outputPaths ?? [],
        status: event.status ?? "completed",
      }})
    }})
    const controller = new AbortController()
    void (async () => {{
      try {{
        for await (const event of ctx.event.subscribe({{ signal: controller.signal }})) {{
          const sessionID = eventSessionID(event)
          const cwd = eventCwd(event)
          if (event.type === "command.executed") {{
            const commandName = String(event?.command ?? event?.properties?.command ?? event?.data?.command ?? "")
            if (commandName.replace(/^[$/]/, "") === "code-knowledge-builder") emit({{ session_id: sessionID, cwd, hook_event_name: "SkillApplied", skill_name: "code-knowledge-builder", ckb_skill_applied: true, event_id: `skill:${{sessionID}}:${{commandName}}` }})
          }}
          if (["session.execution.succeeded", "session.execution.succeeded.1", "session.idle"].includes(event.type)) {{
            const messages = unwrapMessages(await ctx.session.context({{ sessionID }}))
            const latest = [...messages].reverse().find((item) => item?.role === "assistant")
            emit({{ session_id: sessionID, cwd, hook_event_name: "Stop", last_assistant_message: messageText(latest), stop_hook_active: false, event_id: `stop:${{sessionID}}:${{latest?.id ?? event.id ?? event.type}}` }})
          }}
          if (["session.execution.failed", "session.execution.failed.1"].includes(event.type)) emit({{ session_id: sessionID, cwd, hook_event_name: "StopFailure", last_assistant_message: String(event.error?.message ?? event.error ?? "OpenCode 执行失败。"), event_id: `stop-failed:${{sessionID}}:${{event.id ?? event.type}}` }})
          if (event.type === "session.deleted") emit({{ session_id: sessionID, cwd, hook_event_name: "SessionEnd", reason: "other", event_id: `session-end:${{sessionID}}` }})
          if (event.type === "session.compacted") emit({{ session_id: sessionID, cwd, hook_event_name: "PostCompact", trigger: "auto", event_id: `compact:${{sessionID}}:${{event.id ?? "auto"}}` }})
        }}
      }} catch {{}}
    }})()
    return () => {{
      for (const sessionID of seenSessions) emit({{ session_id: sessionID, cwd: sessionCwds.get(sessionID) ?? process.cwd(), hook_event_name: "SessionEnd", reason: "plugin-unload", event_id: `plugin-unload:${{sessionID}}` }})
      controller.abort()
    }}
  }},
}})
'''

def blob_bytes_many(repository: dict[str, Any], files: list[dict[str, Any]]) -> dict[str, bytes]:
    """Read a set of fixed Git blob objects through one binary cat-file session."""
    if not files:
        return {}
    repo = Path(repository["root"])
    unique_oids = list(dict.fromkeys(str(item["blob"]) for item in files))
    query = ("\n".join(unique_oids) + "\n").encode("ascii")
    completed = subprocess.run(
        ["git", "-C", str(repo), "cat-file", "--batch"],
        input=query,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        **background_process_options(),
    )
    if completed.returncode:
        raise StaleSourceError(completed.stderr.decode("utf-8", errors="replace"))
    stream = io.BytesIO(completed.stdout)
    values: dict[str, bytes] = {}
    for requested in unique_oids:
        header = stream.readline().decode("ascii", errors="replace").strip()
        parts = header.split()
        if len(parts) != 3 or parts[1] != "blob":
            raise StaleSourceError(f"Git object is unavailable or is not a blob: {requested}: {header}")
        actual, _kind, size_text = parts
        size = int(size_text)
        content = stream.read(size)
        delimiter = stream.read(1)
        if len(content) != size or delimiter != b"\n" or actual != requested:
            raise StaleSourceError(f"Git cat-file returned an invalid frame for blob: {requested}")
        values[requested] = content
    return {item["path"]: values[str(item["blob"])] for item in files}

def _text_list(value: Any, name: str, maximum: int = 32) -> list[str]:
    if not isinstance(value, list) or not value or len(value) > maximum:
        raise CkbError(f"keyword benchmark {name} must contain 1 to {maximum} strings")
    if any(not isinstance(item, str) or not item.strip() or len(item) > 512 for item in value):
        raise CkbError(f"keyword benchmark {name} contains an invalid string")
    return [item.strip() for item in value]

def load_keyword_benchmark(path: Path) -> list[dict[str, Any]]:
    value = json_load(path.resolve())
    if not isinstance(value, dict) or set(value) != {"schema_version", "cases"}:
        raise CkbError("keyword benchmark file must contain only schema_version and cases")
    if value.get("schema_version") != KEYWORD_BENCHMARK_SCHEMA_VERSION:
        raise CkbError("keyword benchmark schema version mismatch")
    cases = value.get("cases")
    if not isinstance(cases, list) or not 1 <= len(cases) <= MAX_BENCHMARK_CASES:
        raise CkbError(f"keyword benchmark must contain 1 to {MAX_BENCHMARK_CASES} cases")
    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in cases:
        if not isinstance(item, dict):
            raise CkbError("keyword benchmark cases must be objects")
        allowed = {"id", "question", "expected_names", "expected_source_paths", "budget", "max_pages", "profile"}
        if set(item) - allowed:
            raise CkbError("keyword benchmark case contains unsupported fields")
        case_id = item.get("id")
        if not isinstance(case_id, str) or not _CASE_ID.fullmatch(case_id) or case_id in seen:
            raise CkbError("keyword benchmark case id must be unique and bounded")
        seen.add(case_id)
        question = item.get("question")
        if not isinstance(question, str) or not question.strip() or len(question) > 12_000:
            raise CkbError("keyword benchmark question must contain 1 to 12000 characters")
        budget = item.get("budget", 1800)
        max_pages = item.get("max_pages", 8)
        profile = item.get("profile", "fast")
        if isinstance(budget, bool) or not isinstance(budget, int) or not 200 <= budget <= 1_000_000:
            raise CkbError("keyword benchmark budget must be an integer in [200, 1000000]")
        if isinstance(max_pages, bool) or not isinstance(max_pages, int) or not 1 <= max_pages <= 32:
            raise CkbError("keyword benchmark max_pages must be an integer in [1, 32]")
        if profile not in {"fast", "precise"}:
            raise CkbError("keyword benchmark profile must be fast or precise")
        normalized.append(
            {
                "id": case_id,
                "question": question.strip(),
                "expected_names": _text_list(item.get("expected_names"), "expected_names"),
                "expected_source_paths": _text_list(item.get("expected_source_paths"), "expected_source_paths"),
                "budget": budget,
                "max_pages": max_pages,
                "profile": profile,
            }
        )
    return normalized

def _location(result: dict[str, Any], expected_names: list[str], expected_paths: list[str]) -> dict[str, Any]:
    selected = result.get("selected_entities") or []
    names = {
        str(value).casefold()
        for item in selected
        for value in (item.get("name"), item.get("qualified_name"))
        if value
    }
    paths = {str(item.get("source_path")).casefold() for item in selected if item.get("source_path")}
    expected_name_ids = {value.casefold() for value in expected_names}
    expected_path_ids = {value.replace("\\", "/").casefold() for value in expected_paths}
    matched_names = sorted(value for value in expected_names if value.casefold() in names)
    matched_paths = sorted(
        value
        for value in expected_paths
        if value.replace("\\", "/").casefold() in {path.replace("\\", "/") for path in paths}
    )
    total = len(expected_name_ids) + len(expected_path_ids)
    matched = len(matched_names) + len(matched_paths)
    return {
        "score": round(matched / total, 6) if total else 0.0,
        "matched_names": matched_names,
        "matched_source_paths": matched_paths,
        "selected_entities": len(selected),
        "selected_source_paths": len(paths),
        "estimated_tokens": result.get("estimated_tokens"),
        "status": result.get("status"),
    }

def keyword_cache_key(question: str, config: KeywordProviderConfig) -> str:
    validate_provider_config(config)
    material = {
        "input_hash": keyword_input_hash(question),
        "provider": config.provider,
        "model": config.model,
        "version": config.version,
        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
    }
    serialized = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("ascii")).hexdigest()

def _machine_token(value: Any, name: str) -> str:
    if not isinstance(value, str) or not _MACHINE_TOKEN.fullmatch(value):
        raise CkbError(f"keyword provider {name} must be a bounded machine token")
    return value

def validate_provider_config(config: KeywordProviderConfig) -> None:
    if not config.command or any(not isinstance(value, str) or not value for value in config.command):
        raise CkbError("keyword provider command must contain at least one non-empty argument")
    _machine_token(config.provider, "provider")
    _machine_token(config.model, "model")
    _machine_token(config.version, "version")
    if not 0.1 <= config.timeout_seconds <= 300.0:
        raise CkbError("keyword provider timeout must be between 0.1 and 300 seconds")
    if config.retries not in {0, 1}:
        raise CkbError("keyword provider retries must be zero or one")
    for name in config.required_environment:
        if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", name):
            raise CkbError("keyword provider required environment names must be bounded identifiers")

def _bounded_strings(
    value: Any,
    *,
    name: str,
    maximum_items: int,
    maximum_chars: int,
    pattern: re.Pattern[str],
) -> list[str]:
    if not isinstance(value, list) or len(value) > maximum_items:
        raise CkbError(f"keyword provider {name} must be an array with at most {maximum_items} items")
    result: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, str):
            raise CkbError(f"keyword provider {name} items must be strings")
        normalized = item.strip()
        if not normalized or len(normalized) > maximum_chars:
            raise CkbError(f"keyword provider {name} items must contain 1 to {maximum_chars} characters")
        if not pattern.fullmatch(normalized):
            raise CkbError(f"keyword provider {name} contains unsupported characters")
        if _PROMPT_INJECTION.search(normalized):
            raise CkbError(f"keyword provider {name} contains prompt-injection text")
        if _CREDENTIAL_SHAPE.search(normalized):
            raise CkbError(f"keyword provider {name} contains credential-shaped text")
        identity = normalized.casefold()
        if identity in seen:
            raise CkbError(f"keyword provider {name} contains duplicate items")
        seen.add(identity)
        result.append(normalized)
    return result

def _usage(value: Any) -> dict[str, Any]:
    if value is None:
        value = {}
    if not isinstance(value, dict):
        raise CkbError("keyword provider usage must be an object")
    allowed = {"input_tokens", "output_tokens", "total_tokens", "cost_usd"}
    if set(value) - allowed:
        raise CkbError("keyword provider usage contains unsupported fields")
    result: dict[str, Any] = {}
    for name in ("input_tokens", "output_tokens", "total_tokens"):
        item = value.get(name, 0)
        if isinstance(item, bool) or not isinstance(item, int) or item < 0:
            raise CkbError(f"keyword provider usage {name} must be a non-negative integer")
        result[name] = item
    cost = value.get("cost_usd", 0.0)
    if isinstance(cost, bool) or not isinstance(cost, (int, float)) or cost < 0:
        raise CkbError("keyword provider usage cost_usd must be a non-negative number")
    result["cost_usd"] = round(float(cost), 8)
    if result["total_tokens"] and result["total_tokens"] != result["input_tokens"] + result["output_tokens"]:
        raise CkbError("keyword provider usage total_tokens does not match input plus output")
    return result

def parse_provider_json(raw: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise CkbError("keyword provider returned invalid JSON") from exc

def _read_cache(output: Path, question: str, config: KeywordProviderConfig) -> dict[str, Any] | None:
    path = _cache_path(output, keyword_cache_key(question, config))
    if not path.is_file():
        return None
    try:
        record = json_load(path)
        expected = _cache_record(question, config, record.get("response") if isinstance(record, dict) else {})
        if not isinstance(record, dict) or set(record) != _CACHE_FIELDS:
            return None
        for name in _CACHE_FIELDS - {"response"}:
            if record.get(name) != expected.get(name):
                return None
        response = validate_provider_response(record.get("response"), question=question, config=config)
        if response.get("status") != "passed":
            return None
        return response
    except (CkbError, OSError, ValueError, TypeError):
        return None

def audit_keyword_cache(output: Path) -> dict[str, Any]:
    """Check bounded cache records without reading or requiring provider secrets."""

    root = output.resolve() / "workspace-meta" / "keyword-fallback" / "cache"
    if not root.is_dir():
        return {"schema_version": 1, "status": "passed", "records": 0, "errors": []}
    errors: list[str] = []
    records = 0
    for path in sorted(root.glob("*.json")):
        records += 1
        try:
            value = json_load(path)
        except (OSError, ValueError) as exc:
            errors.append(f"{path.name}: invalid cache JSON: {type(exc).__name__}")
            continue
        if not isinstance(value, dict) or set(value) != _CACHE_FIELDS:
            errors.append(f"{path.name}: fields differ from the fixed cache schema")
            continue
        if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION or value.get("status") != "passed":
            errors.append(f"{path.name}: cache status or schema mismatch")
        if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
            errors.append(f"{path.name}: prompt schema mismatch")
        cache_key = value.get("cache_key")
        if not isinstance(cache_key, str) or not re.fullmatch(r"[0-9a-f]{64}", cache_key) or path.stem != cache_key:
            errors.append(f"{path.name}: cache key mismatch")
        input_hash = value.get("input_hash")
        if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
            errors.append(f"{path.name}: input hash is invalid")
        for name in ("provider", "model", "version"):
            try:
                _machine_token(value.get(name), name)
            except CkbError as exc:
                errors.append(f"{path.name}: {exc}")
        serialized = json.dumps(value, ensure_ascii=False)
        if _CREDENTIAL_SHAPE.search(serialized):
            errors.append(f"{path.name}: cache contains credential-shaped text")
    unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
    errors.extend(f"unexpected keyword cache entry: {name}" for name in sorted(unexpected))
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "records": records,
        "errors": errors,
    }

def audit_keyword_fallback(output: Path) -> dict[str, Any]:
    """Audit cache and request records while enforcing the privacy boundary."""

    output = output.resolve()
    cache = audit_keyword_cache(output)
    root = output / "workspace-meta" / "keyword-fallback" / "requests"
    errors = [f"cache: {error}" for error in cache.get("errors", [])]
    records = 0
    if root.is_dir():
        unexpected = [path.name for path in root.iterdir() if not path.is_file() or path.suffix != ".json"]
        errors.extend(f"unexpected keyword request entry: {name}" for name in sorted(unexpected))
        for path in sorted(root.glob("*.json")):
            records += 1
            try:
                value = json_load(path)
            except (OSError, ValueError) as exc:
                errors.append(f"{path.name}: invalid request JSON: {type(exc).__name__}")
                continue
            if not isinstance(value, dict) or set(value) != _REQUEST_FIELDS:
                errors.append(f"{path.name}: fields differ from the fixed request schema")
                continue
            if value.get("schema_version") != KEYWORD_FALLBACK_SCHEMA_VERSION:
                errors.append(f"{path.name}: request schema mismatch")
            if value.get("status") not in {"passed", "fallback", "skipped", "no-quality-gain"}:
                errors.append(f"{path.name}: request status is invalid")
            if value.get("prompt_schema") != KEYWORD_PROMPT_SCHEMA:
                errors.append(f"{path.name}: prompt schema mismatch")
            if value.get("trigger") not in {"forced", "needs-source-read"}:
                errors.append(f"{path.name}: trigger is invalid")
            input_hash = value.get("input_hash")
            if not isinstance(input_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", input_hash):
                errors.append(f"{path.name}: input hash is invalid")
            provider = value.get("provider")
            if not isinstance(provider, dict):
                errors.append(f"{path.name}: provider summary must be an object")
                continue
            for name in ("provider", "model", "version"):
                try:
                    _machine_token(provider.get(name), name)
                except CkbError as exc:
                    errors.append(f"{path.name}: {exc}")
            expected_name = hashlib.sha256(
                json.dumps(
                    {
                        "input_hash": input_hash,
                        "provider": provider.get("provider"),
                        "model": provider.get("model"),
                        "version": provider.get("version"),
                        "prompt_schema": KEYWORD_PROMPT_SCHEMA,
                        "trigger": value.get("trigger"),
                    },
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            if path.stem != expected_name:
                errors.append(f"{path.name}: request identity mismatch")
            serialized = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
            if re.search(r'"(?:question|prompt|command|stdout|stderr|secret|credential)"\s*:', serialized, re.IGNORECASE):
                errors.append(f"{path.name}: request record crosses the privacy boundary")
            if _CREDENTIAL_SHAPE.search(serialized):
                errors.append(f"{path.name}: request record contains credential-shaped text")
    return {
        "schema_version": KEYWORD_FALLBACK_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "cache_records": cache.get("records", 0),
        "request_records": records,
        "errors": errors,
    }

def unique_casefold(values: Sequence[str]) -> list[str]:
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        normalized = value.strip()
        identity = normalized.casefold()
        if normalized and identity not in seen:
            seen.add(identity)
            result.append(normalized)
    return result

def _reject_unknown(value: dict[str, Any], allowed: frozenset[str], location: str) -> None:
    unknown = sorted(set(value) - allowed)
    if unknown:
        raise CkbError(f"unknown knowledge batch manifest field at {location}: {', '.join(unknown)}")

def _object(value: Any, location: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise CkbError(f"knowledge batch manifest {location} must be an object")
    return value

def _absolute(value: Any, location: str) -> Path:
    if not isinstance(value, str) or not value.strip():
        raise CkbError(f"knowledge batch manifest {location} must be a non-empty absolute path")
    path = Path(value).expanduser()
    if not path.is_absolute():
        raise CkbError(f"knowledge batch manifest {location} must be absolute: {value}")
    return path.resolve()

def _normalized_protocol(value: Any) -> str | None:
    if value in {None, "", "none", "absent"}:
        return None
    return str(value)

def _release_for(value: dict[str, Any]) -> KnowledgeRelease | None:
    protocol = _normalized_protocol(value.get("protocol_version"))
    matches = [
        release
        for release in KNOWLEDGE_RELEASES.values()
        if release.ckb_version == value.get("ckb_version")
        and release.schema_version == value.get("schema_version")
        and release.protocol_version == protocol
        and release.source_commit == value.get("release_commit")
    ]
    return matches[0] if len(matches) == 1 else None

def _release_chain(source: KnowledgeRelease, target: KnowledgeRelease) -> list[KnowledgeRelease]:
    chain = [source]
    seen = {source.release_id}
    while chain[-1].release_id != target.release_id:
        next_id = chain[-1].next_release_id
        if not next_id or next_id in seen or next_id not in KNOWLEDGE_RELEASES:
            raise CkbError(f"knowledge release path is incomplete: {source.release_id} -> {target.release_id}")
        seen.add(next_id)
        chain.append(KNOWLEDGE_RELEASES[next_id])
    return chain

def knowledge_version_matrix() -> dict[str, Any]:
    current = _release_for(
        {
            "ckb_version": VERSION,
            "schema_version": SCHEMA_VERSION,
            "protocol_version": AGENT_PROTOCOL_VERSION,
            "release_commit": "2d1ddc4de65c36c2ebe244e3d0556d4b613b2d3d",
        }
    )
    if current is None:
        raise RuntimeError("current CKB release is absent from the knowledge migration matrix")
    return {
        "schema_version": 1,
        "current_release_id": current.release_id,
        "current": {
            "ckb_version": VERSION,
            "schema_version": SCHEMA_VERSION,
            "protocol_version": AGENT_PROTOCOL_VERSION,
        },
        "releases": [
            {
                "release_id": item.release_id,
                "ckb_version": item.ckb_version,
                "schema_version": item.schema_version,
                "protocol_version": item.protocol_version,
                "machine_schema_version": item.machine_schema_version,
                "source_commit": item.source_commit,
                "next_release_id": item.next_release_id,
                "compatible": item.compatible,
            }
            for item in KNOWLEDGE_RELEASES.values()
        ],
    }

def _validate_version(value: Any, location: str) -> dict[str, Any]:
    result = _object(value, location)
    _reject_unknown(result, VERSION_KEYS, location)
    if not isinstance(result.get("ckb_version"), str) or not result["ckb_version"]:
        raise CkbError(f"knowledge batch manifest {location}.ckb_version is invalid")
    if not isinstance(result.get("schema_version"), int) or result["schema_version"] < 1:
        raise CkbError(f"knowledge batch manifest {location}.schema_version is invalid")
    protocol = result.get("protocol_version")
    if protocol is not None and (not isinstance(protocol, str) or not protocol):
        raise CkbError(f"knowledge batch manifest {location}.protocol_version is invalid")
    if not isinstance(result.get("release_commit"), str) or not HEX_SHA1.fullmatch(result["release_commit"]):
        raise CkbError(f"knowledge batch manifest {location}.release_commit must be a full commit SHA-1")
    return result

def _validate_snapshot(value: Any, location: str) -> dict[str, str]:
    result = _object(value, location)
    _reject_unknown(result, SNAPSHOT_KEYS, location)
    for field in SNAPSHOT_KEYS:
        if not isinstance(result.get(field), str) or not HEX_SHA1.fullmatch(result[field]):
            raise CkbError(f"knowledge batch manifest {location}.{field} must be a full Git SHA-1")
    return {"commit": result["commit"], "tree": result["tree"]}
